#:property AllowUnsafeBlocks=true

using System;
using System.Runtime.InteropServices;

// Test stackalloc with Span<nint> and Span<nuint>
Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = (nint)(i * 10);

Console.WriteLine($"Span<nint> (length={signedSpan.Length}, element size={sizeof(nint)} bytes):");
for (int i = 0; i < signedSpan.Length; i++)
    Console.WriteLine($"  [{i}] = {signedSpan[i]}");

Span<nuint> unsignedSpan = stackalloc nuint[3];
unsignedSpan[0] = nuint.MinValue;
unsignedSpan[1] = 42;
unsignedSpan[2] = nuint.MaxValue;

Console.WriteLine($"\nSpan<nuint> (length={unsignedSpan.Length}, element size={sizeof(nuint)} bytes):");
for (int i = 0; i < unsignedSpan.Length; i++)
    Console.WriteLine($"  [{i}] = {unsignedSpan[i]}");

Console.WriteLine($"\nnint  size: {sizeof(nint)} bytes ({sizeof(nint) * 8}-bit)");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes ({sizeof(nuint) * 8}-bit)");
Console.WriteLine("\n✅ stackalloc with Span<nint>/Span<nuint> works!");

